    NetworkChanges.save(context,"external",J.obj("proxy","http://127.0.0.1:19201"),written);JSONObject unrelated=NetworkChanges.pending(context);check("A hash match without lineage never rebases another candidate",!NetworkChanges.rebase(context,lineage)&&NetworkChanges.pending(context).toString().equals(unrelated.toString()));
    NetworkChanges.save(context,"external",J.obj("proxy","http://127.0.0.1:19202"),before,NetworkChanges.lineage("newer-C",written,before,1));unrelated=NetworkChanges.pending(context);check("A newer independent candidate remains unchanged by A rollback",!NetworkChanges.rebase(context,lineage)&&NetworkChanges.pending(context).toString().equals(unrelated.toString()));
    NetworkChanges.save(context,"external",J.obj("proxy","http://127.0.0.1:19203"),written,lineage);JSONObject failedBefore=NetworkChanges.pending(context);SecretStore.failSlotOnce="pending-network";boolean failed=false;try{NetworkChanges.rebase(context,lineage);}catch(java.io.IOException expected){failed=true;}check("Failed rebase publication reports a real storage failure",failed);check("Failed rebase publication preserves the latest candidate record",NetworkChanges.pending(context).toString().equals(failedBefore.toString()));check("A later successful retry can rebase that preserved candidate",NetworkChanges.rebase(context,lineage));
