    check("Current exact pointer can cancel its desired configuration",NetworkChanges.clearIfCurrent(context,latestPointer));
    check("Exact pointer cleanup removes the desired record and both owned payloads",NetworkChanges.pending(context).length()==0&&vault.get(latestEntry)==null&&vault.get(latestExit)==null);
    check("Canceling desired configuration keeps the active baseline unchanged",NetworkChanges.hash(context).equals(before));
