    System.out.println(J.obj("passed",checks.length(),"total",checks.length(),"checks",checks,"actualAndroidExecution",false,"actualGeckoExecution",false,"actualNativeExecution",false,"scope","Production encrypted-record logic executed with host plain atomic-file fixtures; exact baseline lineage, compare-and-clear cancellation pointers and provider payload retention only. Actual browser send and safe-idle fences have a separate Android suite.").toString());
